int jump_search(const int a[], int n, int x) {
  int step = (int)sqrt(n), prev = 0;
  while (a[(step < n ? step : n) - 1] < x) {
    prev = step; step += (int)sqrt(n);
    if (prev >= n) return -1;
  }
  for (int i = prev; i < (step < n ? step : n); i++)
    if (a[i] == x) return i;
  return -1;
}
